CREATE TABLE IF NOT EXISTS elections (id INTEGER PRIMARY KEY, name TEXT NOT NULL, event_date DATE NOT NULL, synthetic BOOLEAN NOT NULL DEFAULT FALSE);
CREATE TABLE IF NOT EXISTS territories (id INTEGER PRIMARY KEY, parent_id INTEGER REFERENCES territories(id), kind TEXT NOT NULL, code TEXT NOT NULL, name TEXT NOT NULL, UNIQUE(kind, code));
CREATE TABLE IF NOT EXISTS polling_places (id INTEGER PRIMARY KEY, territory_id INTEGER NOT NULL REFERENCES territories(id), name TEXT NOT NULL, synthetic BOOLEAN NOT NULL DEFAULT FALSE);
CREATE TABLE IF NOT EXISTS polling_tables (id INTEGER PRIMARY KEY, place_id INTEGER NOT NULL REFERENCES polling_places(id), province_code TEXT NOT NULL, municipality_code TEXT NOT NULL, district TEXT NOT NULL, section TEXT NOT NULL, label TEXT NOT NULL, synthetic BOOLEAN NOT NULL DEFAULT FALSE, UNIQUE(province_code, municipality_code, district, section, label));
CREATE TABLE IF NOT EXISTS users (id INTEGER PRIMARY KEY, display_name TEXT NOT NULL, role TEXT NOT NULL CHECK(role IN ('apoderado','supervisor','organizacion','administrador')), active BOOLEAN NOT NULL DEFAULT TRUE, can_view_results BOOLEAN NOT NULL DEFAULT FALSE, synthetic BOOLEAN NOT NULL DEFAULT FALSE);
CREATE TABLE IF NOT EXISTS user_phones (user_id INTEGER PRIMARY KEY REFERENCES users(id), phone_e164 TEXT NOT NULL UNIQUE);
CREATE TABLE IF NOT EXISTS assignments (user_id INTEGER NOT NULL REFERENCES users(id), table_id INTEGER NOT NULL REFERENCES polling_tables(id), PRIMARY KEY(user_id, table_id));
CREATE TABLE IF NOT EXISTS sessions (id TEXT PRIMARY KEY, user_id INTEGER NOT NULL REFERENCES users(id), expires_at TIMESTAMP NOT NULL, revoked_at TIMESTAMP);
CREATE TABLE IF NOT EXISTS candidacies (id INTEGER PRIMARY KEY, election_id INTEGER NOT NULL REFERENCES elections(id), chamber TEXT NOT NULL CHECK(chamber IN ('congreso','senado')), constituency_code TEXT NOT NULL, name TEXT NOT NULL, synthetic BOOLEAN NOT NULL DEFAULT FALSE);
CREATE TABLE IF NOT EXISTS candidates (id INTEGER PRIMARY KEY, candidacy_id INTEGER NOT NULL REFERENCES candidacies(id), name TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS documents (id TEXT PRIMARY KEY, election_id INTEGER NOT NULL REFERENCES elections(id), table_id INTEGER NOT NULL REFERENCES polling_tables(id), chamber TEXT NOT NULL CHECK(chamber IN ('congreso','senado')), document_type TEXT NOT NULL, version INTEGER NOT NULL, status TEXT NOT NULL CHECK(status IN ('pending_upload','received','processing','extracted','pending_review','validated','rejected','recoverable_error')), uploader_id INTEGER NOT NULL REFERENCES users(id), idempotency_key TEXT NOT NULL, current_validated BOOLEAN NOT NULL DEFAULT FALSE, conflict BOOLEAN NOT NULL DEFAULT FALSE, blank_votes INTEGER CHECK(blank_votes >= 0), null_votes INTEGER CHECK(null_votes >= 0), total_votes INTEGER CHECK(total_votes >= 0), created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, UNIQUE(uploader_id,idempotency_key), UNIQUE(election_id,table_id,chamber,document_type,version));
CREATE UNIQUE INDEX IF NOT EXISTS one_current_document ON documents(election_id,table_id,chamber,document_type) WHERE current_validated;
CREATE TABLE IF NOT EXISTS document_images (id TEXT PRIMARY KEY, document_id TEXT NOT NULL REFERENCES documents(id), object_key TEXT NOT NULL UNIQUE, mime_type TEXT NOT NULL, byte_size INTEGER, sha256 TEXT, width_px INTEGER, height_px INTEGER, exif_orientation INTEGER, received_at TIMESTAMP);
CREATE TABLE IF NOT EXISTS processing_jobs (id TEXT PRIMARY KEY, document_id TEXT NOT NULL UNIQUE REFERENCES documents(id), status TEXT NOT NULL CHECK(status IN ('queued','leased','done','failed')), attempts INTEGER NOT NULL DEFAULT 0, available_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, lease_until TIMESTAMP, last_error TEXT);
CREATE TABLE IF NOT EXISTS extractions (id TEXT PRIMARY KEY, document_id TEXT NOT NULL UNIQUE REFERENCES documents(id), provider TEXT NOT NULL, model_version TEXT NOT NULL, config_json TEXT NOT NULL, raw_json TEXT NOT NULL, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS reviews (id TEXT PRIMARY KEY, document_id TEXT NOT NULL REFERENCES documents(id), reviewer_id INTEGER NOT NULL REFERENCES users(id), values_json TEXT NOT NULL, decision TEXT NOT NULL CHECK(decision IN ('validated','rejected')), created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS document_votes (document_id TEXT NOT NULL REFERENCES documents(id), candidacy_id INTEGER NOT NULL REFERENCES candidacies(id), votes INTEGER NOT NULL CHECK(votes >= 0), PRIMARY KEY(document_id,candidacy_id));
CREATE TABLE IF NOT EXISTS audit_events (id TEXT PRIMARY KEY, document_id TEXT REFERENCES documents(id), actor_id INTEGER REFERENCES users(id), action TEXT NOT NULL, details_json TEXT NOT NULL, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP);
